@namespace sv_7ee51e9183de4269a06655d2acf3532e.Components.Pages.Settings
@using sv_7ee51e9183de4269a06655d2acf3532e.Services

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (settings is null)
    {
        <p>Loading...</p>
        return;
    }

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            <label class="radio-item">
                <input type="radio" name="theme" value="Light" checked="@(theme == "Light")" @onchange="() => theme = \"Light\"" />
                <span>Light</span>
            </label>
            <label class="radio-item">
                <input type="radio" name="theme" value="Dark" checked="@(theme == "Dark")" @onchange="() => theme = \"Dark\"" />
                <span>Dark</span>
            </label>
            <label class="radio-item">
                <input type="radio" name="theme" value="System" checked="@(theme == "System")" @onchange="() => theme = \"System\"" />
                <span>System</span>
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            <label class="radio-item">
                <input type="radio" name="fontSize" value="Small" checked="@(fontSize == "Small")" @onchange="() => fontSize = \"Small\"" />
                <span>Small</span>
            </label>
            <label class="radio-item">
                <input type="radio" name="fontSize" value="Medium" checked="@(fontSize == "Medium")" @onchange="() => fontSize = \"Medium\"" />
                <span>Medium</span>
            </label>
            <label class="radio-item">
                <input type="radio" name="fontSize" value="Large" checked="@(fontSize == "Large")" @onchange="() => fontSize = \"Large\"" />
                <span>Large</span>
            </label>
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="language" class="form-control">
            <option value="en">English</option>
            <option value="es">Spanish</option>
            <option value="fr">French</option>
            <option value="de">German</option>
            <option value="ja">Japanese</option>
            <option value="zh">Chinese</option>
        </select>
    </div>

    <div class="form-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="compactMode" class="toggle-switch" />
            <span>Compact Mode</span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p>This is a preview of how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            <button class="btn btn-primary">Sample Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save")
        </button>
    </div>

    @if (showSuccess)
    {
        <div class="toast toast-success">Appearance settings saved!</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private bool isSaving;
    private bool showSuccess;

    protected override void OnParametersSet()
    {
        if (settings is not null)
        {
            theme = settings.Theme;
            fontSize = settings.FontSize;
            language = settings.Language;
            compactMode = settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{theme.ToLowerInvariant()} preview-font-{fontSize.ToLowerInvariant()}";
        if (compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        isSaving = true;
        var updated = new AppearanceSettings(theme, fontSize, language, compactMode);
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

