@page "/settings"
@namespace sv_7ee51e9183de4269a06655d2acf3532e.Components.Pages.Settings
@using sv_7ee51e9183de4269a06655d2acf3532e.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection profile="@userProfile" OnSave="SaveProfile" />
                break;
            case "Notifications":
                <NotificationsSection prefs="@notificationPrefs" OnSave="SaveNotifications" />
                break;
            case "Security":
                <SecuritySection settings="@securitySettings"
                                 OnChangePassword="HandleChangePassword"
                                 OnRevokeSession="HandleRevokeSession" />
                break;
            case "Appearance":
                <AppearanceSection settings="@appearanceSettings" OnSave="SaveAppearance" />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private UserProfile? userProfile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadSection(activeSection);
    }

    private async Task SetActiveSection(string section)
    {
        activeSection = section;
        await LoadSection(section);
    }

    private async Task LoadSection(string section)
    {
        switch (section)
        {
            case "Profile":
                userProfile ??= await SettingsService.GetProfileAsync();
                break;
            case "Notifications":
                notificationPrefs ??= await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security":
                securitySettings ??= await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                appearanceSettings ??= await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfile(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        userProfile = profile;
    }

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        notificationPrefs = prefs;
    }

    private async Task HandleChangePassword(string passwordData)
    {
        var parts = passwordData.Split('|', 2);
        await SettingsService.ChangePasswordAsync(parts[0], parts[1]);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        appearanceSettings = settings;
    }
}

.settings-page {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--sidebar-bg, #f8f9fa);
    border-right: 1px solid var(--border-color, #dee2e6);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.2s, border-left 0.2s;
    border-left: 3px solid transparent;
    font-size: 0.95rem;
}

.settings-nav-item:hover {
    background-color: var(--hover-bg, #e9ecef);
}

.settings-nav-item.active {
    background-color: var(--active-bg, #e3f2fd);
    border-left-color: var(--primary-color, #1976d2);
    font-weight: 600;
    color: var(--primary-color, #1976d2);
}

.settings-nav-icon {
    font-size: 1.2rem;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--heading-color, #212529);
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    font-weight: 600;
}

/* Form Controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: var(--label-color, #495057);
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color, #ced4da);
    border-radius: 0.375rem;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: var(--primary-color, #1976d2);
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.15);
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.2s, opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background-color: var(--primary-color, #1976d2);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1565c0;
}

.btn-secondary {
    background-color: #6c757d;
    color: white;
}

.btn-secondary:hover:not(:disabled) {
    background-color: #5a6268;
}

.btn-danger {
    background-color: #dc3545;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background-color: #c82333;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid var(--border-color, #dee2e6);
}

.avatar-url-display {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
}

/* Toggles */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-switch {
    width: 1.2rem;
    height: 1.2rem;
    cursor: pointer;
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: var(--card-bg, #f8f9fa);
    border-radius: 0.375rem;
    border: 1px solid var(--border-color, #dee2e6);
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 0.375rem;
    margin-bottom: 1.5rem;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: var(--card-bg, #f8f9fa);
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

.panel-header:hover {
    background: var(--hover-bg, #e9ecef);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid var(--border-color, #dee2e6);
}

/* Two-Factor */
.two-factor-section {
    margin-bottom: 1.5rem;
}

.status-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.status-indicator {
    padding: 0.3rem 0.75rem;
    border-radius: 1rem;
    font-size: 0.85rem;
    font-weight: 500;
}

.status-enabled {
    background: #d4edda;
    color: #155724;
}

.status-disabled {
    background: #f8d7da;
    color: #721c24;
}

.last-change {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #6c757d;
}

/* Sessions Table */
.sessions-section {
    margin-top: 1.5rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--border-color, #dee2e6);
}

.sessions-table th {
    background: var(--card-bg, #f8f9fa);
    font-weight: 600;
}

.current-session-badge {
    font-size: 0.8rem;
    color: #6c757d;
    font-style: italic;
}

/* Radio Groups */
.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

/* Preview Area */
.preview-area {
    margin-top: 1.5rem;
