@page "/settings"
@namespace sv_7ee51e9183de4269a06655d2acf3532e.Components.Pages.Settings
@using sv_7ee51e9183de4269a06655d2acf3532e.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection profile="@userProfile" OnSave="SaveProfile" />
                break;
            case "Notifications":
                <NotificationsSection prefs="@notificationPrefs" OnSave="SaveNotifications" />
                break;
            case "Security":
                <SecuritySection settings="@securitySettings"
                                 OnChangePassword="HandleChangePassword"
                                 OnRevokeSession="HandleRevokeSession" />
                break;
            case "Appearance":
                <AppearanceSection settings="@appearanceSettings" OnSave="SaveAppearance" />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private UserProfile? userProfile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadSection(activeSection);
    }

    private async Task SetActiveSection(string section)
    {
        activeSection = section;
        await LoadSection(section);
    }

    private async Task LoadSection(string section)
    {
        switch (section)
        {
            case "Profile":
                userProfile ??= await SettingsService.GetProfileAsync();
                break;
            case "Notifications":
                notificationPrefs ??= await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security":
                securitySettings ??= await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                appearanceSettings ??= await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfile(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        userProfile = profile;
    }

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        notificationPrefs = prefs;
    }

    private async Task HandleChangePassword(string passwordData)
    {
        var parts = passwordData.Split('|', 2);
        await SettingsService.ChangePasswordAsync(parts[0], parts[1]);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        appearanceSettings = settings;
    }
}

